// next.config.js (Multi-Zones Example)
// This is the configuration for the main 'Store' application

module.exports = {
  async rewrites() {
    return [
      {
        // If a user visits the main site but goes to /blog...
        source: '/blog',
        // Secretly proxy the request to Team B's completely separate Next.js app!
        // The user's browser URL stays at mystore.com/blog
        destination: 'https://blog-app-team-b.vercel.app/blog',
      },
      {
        source: '/blog/:path*',
        destination: 'https://blog-app-team-b.vercel.app/blog/:path*',
      }
    ]
  }
}
